 "content": "def transform(grid):
    out = [row[:] for row in grid]
    zeros = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 0]
    if not zeros:
        return out
    rows = {r for r, _ in zeros}
    cols = {c for _, c in zeros}
    # Zero cross through the marker; retain the distinguished 2 markers.
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r in rows or c in cols) and grid[r][c] != 2:
                out[r][c] = 0
    return out
